下面的函数意图是释放整棵树，但存在**悬垂访问**。指出问题并给出正确写法。

```c
void destroy(Node *root) {
    if (!root) return;
    free(root);
    destroy(root->left);
    destroy(root->right);
}
```

answer.reference_code:
void destroy(Node *root) {
    if (!root) return;
    destroy(root->left);    /* 先递归释放左子树 */
    destroy(root->right);   /* 再递归释放右子树 */
    free(root);             /* 最后释放自己 —— 必须后序 */
}

/* 非递归：显式栈手动模拟递归 */
int* inorderTraversal(struct TreeNode* root, int* returnSize) {
    int *res = malloc(100 * sizeof(int));
    struct TreeNode *stk[100];
    int top = 0, n = 0;
    struct TreeNode *cur = root;
    while (cur || top > 0) {
        while (cur) { stk[top++] = cur; cur = cur->left; }  /* 一路向左 */
        cur = stk[--top];
        res[n++] = cur->val;                                 /* 左完了访问根 */
        cur = cur->right;                                    /* 转右子树 */
    }
    *returnSize = n;
    return res;
}

/* 方案一：中序遍历判严格递增（推荐） */
static long prev;
static int inorder(struct TreeNode *n) {
    if (!n) return 1;
    if (!inorder(n->left)) return 0;
    if (n->val <= prev) return 0;   /* 必须严格递增 */
    prev = n->val;
    return inorder(n->right);
}
int isValidBST(struct TreeNode* root) {
    prev = LONG_MIN;
    return inorder(root);
}

/* 队列 + 逐层切分 */
int** levelOrder(struct TreeNode* root, int* returnSize, int** returnColumnSizes) {
    int **res = malloc(2000 * sizeof(int*));
    int *cols = malloc(2000 * sizeof(int));
    struct TreeNode *q[2000];
    int head = 0, tail = 0, levels = 0;
    if (root) q[tail++] = root;
    while (head < tail) {
        int len = tail - head;           /* 当前层的节点数 */
        int *row = malloc(len * sizeof(int));
        for (int i = 0; i < len; i++) {
            struct TreeNode *n = q[head++];
            row[i] = n->val;
            if (n->left)  q[tail++] = n->left;
            if (n->right) q[tail++] = n->right;
        }
        res[levels] = row;
        cols[levels++] = len;
    }
    *returnSize = levels;
    *returnColumnSizes = cols;
    return res;
}
